   122	        GITERR_CHECK_ALLOC(tag->tag_name);
   123	
   124	        memcpy(tag->tag_name, buffer, text_len);
   125	        tag->tag_name[text_len] = '\0';
   126	
   127	        buffer = search + 1;
   128	
   129	        tag->tagger = NULL;
   130	        if (buffer < buffer_end && *buffer != '\n') {
   131	                tag->tagger = git__malloc(sizeof(git_signature));
