   134	                if (git_signature__parse(tag->tagger, &buffer, buffer_end, "tagger ", '\n') < 0)
   135	                        return -1;
   136	        }
   137	
   138	        tag->message = NULL;
   139	        if (buffer < buffer_end) {
   140	                /* If we're not at the end of the header, search for it */
   141	                if( *buffer != '\n' ) {
   142	                        search = strstr(buffer, "\n\n");
   143	                        if (search)
