   145	                        else
   146	                                return tag_error("tag contains no message");
   147	                }
   148	
   149	                text_len = buffer_end - ++buffer;
   150	
   151	                GITERR_CHECK_ALLOC_ADD(&alloc_len, text_len, 1);
   152	                tag->message = git__malloc(alloc_len);
   153	                GITERR_CHECK_ALLOC(tag->message);
